import { connect } from "react-redux";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import React, { useState } from "react";
import { Input, Button } from "antd";
import { UserOutlined,LockOutlined } from "@ant-design/icons";
;
function Home() {

    const [formData, setFormData] = useState({
        username: "",
        password: "",   
    });

    const {
        username,
        password,
    } = formData;

    const onChange = e => setFormData({ ...formData, [e.target.name]: e.target.value });
    const navigate = useNavigate();

    const onSubmit = async e => {
        e.preventDefault();
        
        try {
            //Solicitar token
            const response = await axios.post("http://localhost:3001/api/token/", {
                username,
                password,
            });

            //Guardar token en el local storage
            localStorage.setItem("access", response.data.access);
            localStorage.setItem("refresh", response.data.refresh);

            //Decodificar token
            const decodedToken = JSON.parse(atob(response.data.access.split(".")[1]));
            console.log("Payload del token:", decodedToken);

            //Verificar usuario
            if (decodedToken.is_superuser) {
                navigate("/admin-page");
            } else {
                navigate("/user-page");
            }
        }catch (error) {
            console.error("Error al iniciar sesión:", error);
            alert("Usuario o contraseña incorrectos");
        }
    };

  return (
    <>
        <form
            onSubmit={e => onSubmit(e)}
            style={{
                display: "flex", // Usamos Flexbox
                flexDirection: "column", // Los elementos estarán en columna (uno debajo del otro)
                justifyContent: "center", // Centra los elementos verticalmente
                alignItems: "center", // Centra los elementos horizontalmente
                height: "100vh", // Asegura que el contenedor ocupe toda la altura de la página
            }}
        >
            {/* Usuario */}
            <Input 
                name="username"
                value={username}
                onChange={e => onChange(e)}
                type="text"
                required
                placeholder="Nombre de Usuario" 
                prefix={<UserOutlined />} 
                className="input-small"/>
            <br />

            {/* Contraseña */}
            <Input 
                name="password"
                value={password}
                onChange={e => onChange(e)}
                type="password"
                required
                placeholder="Contraseña de Usuario" 
                prefix={<LockOutlined />} 
                className="input-small" />
            <br />

            {/* Botón de Acción */}
            <Button 
                type="primary" 
                htmlType="submit"
                className="input-small"
            > 
                Iniciar Sesión
            </Button>
        </form>
    </>
  );
}
export default Home;